/**
 * 从 chapters/ch03 独立题页 HTML 解析 #ct 与题面元数据，生成：
 * - assets/ch03-problems-bundle.js（供 index.html）
 *
 * 运行：npm run build:ch03
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { parse } from 'node-html-parser';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.join(__dirname, '..');
const manifestPath = path.join(__dirname, 'ch03-manifest.json');
const bundleOut = path.join(repoRoot, 'assets', 'ch03-problems-bundle.js');

function readManifest() {
  const raw = fs.readFileSync(manifestPath, 'utf8');
  return JSON.parse(raw);
}

function extractCodeTableHtml(table) {
  const parts = [];
  for (const child of table.childNodes) {
    if (child.nodeType === 1 && String(child.tagName).toLowerCase() === 'tr') {
      parts.push(child.outerHTML);
    }
  }
  return parts.join('\n');
}

function parseProblemPage(absPath, expectedNum) {
  const html = fs.readFileSync(absPath, 'utf8');
  const root = parse(html);
  const probLink = root.querySelector('a#probLink');
  const probNumEl = root.querySelector('#probNum');
  const probNameEl = root.querySelector('#probName');
  const table = root.querySelector('table#ct');

  if (!table) throw new Error(`No table#ct in ${absPath}`);
  if (!probLink || !probNumEl || !probNameEl) {
    throw new Error(`Missing prob title elements in ${absPath}`);
  }

  const num = probNumEl.textContent.trim().replace(/\.$/, '');
  const name = probNameEl.textContent.trim();
  const url = probLink.getAttribute('href') || '';
  if (expectedNum && num !== expectedNum) {
    console.warn(`[build-ch03] ${absPath}: probNum "${num}" !== manifest num "${expectedNum}"`);
  }

  const codeTableHtml = extractCodeTableHtml(table);
  return { num, name, url, codeTableHtml };
}

function toJsObject(item) {
  return `    {
      num: ${JSON.stringify(item.num)},
      name: ${JSON.stringify(item.name)},
      url: ${JSON.stringify(item.url)},
      codeTableHtml: ${JSON.stringify(item.codeTableHtml)},
    }`;
}

function main() {
  const { problems } = readManifest();
  const bfsTree = [];
  const topo = [];
  const dijkstra = [];

  for (const entry of problems) {
    const absPath = path.join(repoRoot, entry.path);
    if (!fs.existsSync(absPath)) {
      throw new Error(`Missing file: ${entry.path}`);
    }
    const p = parseProblemPage(absPath, entry.num);
    if (entry.group === 'bfsTree') bfsTree.push(p);
    else if (entry.group === 'topo') topo.push(p);
    else if (entry.group === 'dijkstra') dijkstra.push(p);
    else throw new Error(`Unknown group "${entry.group}" for ${entry.path}`);
  }

  const bundleJs = `/** Generated by scripts/build-ch03-index-bundle.mjs — do not edit */
(function () {
  'use strict';

  window.CH03_FILL_BFS_TREE = [
${bfsTree.map(toJsObject).join(',\n')}
  ];

  window.CH03_FILL_TOPO = [
${topo.map(toJsObject).join(',\n')}
  ];

  window.CH03_FILL_DIJKSTRA = [
${dijkstra.map(toJsObject).join(',\n')}
  ];
})();
`;

  fs.writeFileSync(bundleOut, bundleJs, 'utf8');
  console.log(`Wrote ${bundleOut}`);
}

main();
